import React, { useState } from "react";
import FinancialCard from "./FinancialCard";
import FinancialBreakdown from "./FinancialBreakdown";
import PIDropDown from "@components/core-components/dropdown";

interface FinancialOverviewProps {
  balance: string;
  bonusWallet: string;
  profitability: string;
  grossGamingRevenue: string;
  sportsBookAmount: string;
  casinoAmount: string;
  exchangeAmount: string;
}

const FinancialOverview: React.FC<FinancialOverviewProps> = ({
  balance,
  bonusWallet,
  profitability,
  grossGamingRevenue,
  sportsBookAmount,
  casinoAmount,
  exchangeAmount,
}) => {
  const [selectedValue, setSelectedValue] = useState("EUR");
  const financialData = [
    {
      color: "bg-sky-400",
      amount: balance,
      label: "Balance/EUR, Approximation",
      dropDown: (
        <PIDropDown
          options={[
            { value: "EUR", label: "EUR" },
            { value: "USD", label: "USD" },
            { value: "INR", label: "INR" },
            { value: "TRY", label: "TRY" },
          ]}
          value={selectedValue}
          onChange={(value) => setSelectedValue(value)}
          dropDownlistClassNames="w-[185px] top-[100px] right-[0px]"
          className="h-[25px] w-[25px]"
        />
      ),
    },
    { color: "bg-green-400", amount: bonusWallet, label: "Bonus Wallet" },
    {
      color: "bg-amber-300",
      amount: profitability,
      label: "Player Profitability For Us",
    },
    {
      color: "bg-rose-500",
      amount: grossGamingRevenue,
      label: "Gross Gaming Revenue",
    },
  ];

  return (
    <section className="flex flex-col grow shrink min-w-[240px] w-[763px] max-md:max-w-full ">
      <div className="flex flex-wrap gap-3 items-center w-full max-md:max-w-full relative">
        {financialData.map((data, index) => (
          <FinancialCard key={index} {...data} />
        ))}
      </div>
      <FinancialBreakdown
        sportsBookAmount={sportsBookAmount}
        casinoAmount={casinoAmount}
        exchangeAmount={exchangeAmount}
      />
    </section>
  );
};

export default FinancialOverview;
