import React from "react";

interface CheckBoxProps {
  classNames?: string;
  onChange?: () => void;
  checked: boolean;
  disabled?: boolean;
}

const Checkbox: React.FC<CheckBoxProps> = ({
  onChange,
  classNames = "",
  checked,
  disabled = false,
}) => {
  return (
    <div className={`flex flex-row items-center ${classNames}`}>
      <input
        type="checkbox"
        onChange={onChange}
        checked={checked}
        disabled={disabled}
        className="form-checkbox h-5 w-5 text-blue-600 border-gray-300 rounded focus:ring focus:ring-blue-500 focus:ring-opacity-50 disabled:bg-gray-200 disabled:text-gray-500"
      />
    </div>
  );
};

export default Checkbox;
