import React, { useContext, useState } from "react";
import { TabContext } from "./TabContext";

interface TabProps {
  label: string;
  isActive: boolean;
}

const TabNavigation: React.FC<TabProps> = () => {
  const [tabs, setTabs] = useState(["Deposit", "Withdraw"]);
  const { activeTab, setActiveTab } = useContext(TabContext);
  return (
    <>
      <nav className="flex gap-4 items-center self-start">
        {tabs.map((tab, index) => (
          <button
            className={`gap-1 self-stretch px-2.5 pb-5 my-auto font-${
              tab === activeTab ? "semibold" : "medium"
            } ${
               tab === activeTab
                ? "text-blue-500 border-b-2 border-solid border-b-blue-500"
                : "text-slate-600 rounded-lg"
            }`}
            onClick={() => {
              setActiveTab(tab);
            }}
          >
            {tab}
          </button>
        ))}
      </nav>
    </>
  );
};

export default TabNavigation;
