import React from 'react';

interface FinancialBreakdownProps {
  sportsBookAmount: string;
  casinoAmount: string;
  exchangeAmount: string;
}

const FinancialBreakdown: React.FC<FinancialBreakdownProps> = ({
  sportsBookAmount,
  casinoAmount,
  exchangeAmount
}) => {
  const breakdownData = [
    { color: "green-500", label: "Sportsbook", percentage: "55%", amount: sportsBookAmount },
    { color: "orange-500", label: "Casino", percentage: "25%", amount: casinoAmount },
    { color: "indigo-500", label: "Exchange", percentage: "20%", amount: exchangeAmount }
  ];

  return (
    <div className="flex flex-col mt-6 w-full max-md:max-w-full">
      <div className="flex flex-wrap gap-1 items-center w-full max-md:max-w-full">
        {breakdownData.map((data, index) => (
          <div key={index} className={`flex gap-2.5 self-stretch my-auto h-2 bg-${data.color} rounded-sm min-h-[8px] ${index === 2 ? 'flex-1 shrink basis-0 min-w-[240px] w-[317px]' : 'min-w-[240px]'}`} />
        ))}
      </div>
      <div className="flex flex-wrap gap-10 items-center self-start mt-5 text-sm font-medium leading-loose text-slate-600 max-md:max-w-full">
        {breakdownData.map((data, index) => (
          <div key={index} className="flex gap-2 items-center self-stretch my-auto">
            <div className={`flex shrink-0 self-stretch my-auto w-2 h-2 bg-${data.color} rounded-3xl`} />
            <div className="self-stretch my-auto">
              <span className="leading-4 text-slate-600">{data.label} ({data.percentage}) - </span>{" "}
              <span className="font-semibold leading-4 text-slate-600">{data.amount}</span>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default FinancialBreakdown;