import React, {
  ChangeEvent,
  useCallback,
  useMemo,
  useRef,
  useState,
} from "react";
import { PDataGrid } from "@components/core-components/grid/PDataGrid";
import Icon from "@components/core-components/icon";
import { useBaseQuery } from "api/core/useBaseQuery";
import "ag-grid-enterprise";

import { AgGridReact } from "ag-grid-react";
import GridFilter from "pages/players/list/components/GridFilter";
import DetailCellRenderer from "pages/players/list/components/DetailCellRenderer";
import { PLAYERS_API_URLS } from "config/apiUrls";
function NotesTable() {
  const [closeFilters, setCloseFilters] = useState(true);
  const [quickFilterText, setQuickFilterText] = useState("");
  const { data } = useBaseQuery<[]>({
    endpoint: PLAYERS_API_URLS.GET_PLAYERS,
  });

  const gridRef = useRef<AgGridReact>(null);

  const onFilterTextBoxChanged = useCallback(
    (e: ChangeEvent<HTMLInputElement>) => {
      gridRef.current!.api.setGridOption(
        "quickFilterText",
        (document.getElementById("filter-text-box") as HTMLInputElement).value
      );
      setQuickFilterText(e.target.value);
    },
    []
  );
  const [colDefs, setColDefs] = useState<any>([
    {
      headerName: "DATE",
      field: "date",
      autoHeight: true,
      floatingFilter: true,
      filter: "agTextColumnFilter",
      cellEditor: 'agDateCellEditor',
      cellClass: "ellipsis-cell",
      cellStyle: {
        display: "flex",
        alignItems: "center",
        justifyContent: "flex-start",
      },
      width: 45,
    },
    {
      headerName: "CREATED BY",
      field: "username",
      width: 45,
      autoHeight: true,
      filter: "agTextColumnFilter",
      floatingFilter: true,
      cellClass: "ellipsis-cell text-primary",
      cellStyle: {
        overflowX: "hidden",
        display: "flex",
        alignItems: "center",
        justifyContent: "flex-start",
        color: "var(--Primary-Primary, #666CFF)",
        fontFamily: '"SF Pro Display", sans-serif',
        fontSize: "14px",
        fontStyle: "normal",
        fontWeight: "600",
        lineHeight: "normal",
        textDecoration: "underline",
      },
    },
    {
      headerName: "NOTE",
      field: "note",
      filter: "agTextColumnFilter",
      width: 200,
      autoHeight: true,
      floatingFilter: true,
      cellClass: "ellipsis-cell",
      cellStyle: {
        overflowX: "hidden",
        display: "flex",
        alignItems: "center",
        justifyContent: "flex-start",
      },
    },
    {
      headerName: "PROCESS",
      field: "process",
      width: 60,
      autoHeight: true,
      filter: true,
      floatingFilter: true,
      cellClass: "ellipsis-cell",
      cellStyle: {
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      },
      cellRenderer: (params: any) => {
        return (
          <span>
            {params.value ? (
              <>
                <Icon className="pr-2" iconName="verified" />
              </>
            ) : (
              <>
                <Icon iconName="cancel" />
              </>
            )}
          </span>
        );
      },
    },
    
  ]);
  const onGridReady = useCallback((params: any) => {
    params.api.sizeColumnsToFit();
  }, []);

  return (
    <>
      {/* <h1 className="text-2xl font-bold mb-4">Player Management</h1> */}
      <div className="bg-white flex flex-col w-full max-md:max-w-full">
        {/* <QuickFilterHeader
          handleSearch={onFilterTextBoxChanged}
          searchText={quickFilterText}
          closeFilters={closeFilters}
          setCloseFilters={setCloseFilters}
        /> */}

        <div className="flex flex-col flex-grow ">
          <GridFilter showSimpleFilters={!closeFilters} onApplyFilters={() => {}} />
          <div className="flex-grow h-screen ">
            <PDataGrid
              gridRef={gridRef}
              DetailCellRenderer={DetailCellRenderer}
              colDefs={colDefs}
              rowData={data || []}
              onGridReady={onGridReady}
            />
          </div>
        </div>
      </div>
    </>
  );
}

export default NotesTable;
