import React from "react";

interface RadioProps {
  onChange?: () => void;
  checked: boolean;
  disabled?: boolean;
}

const Radio: React.FC<RadioProps> = ({
  onChange,
  checked,
  disabled = false,
}) => {
  return (
    <>
      <input
        type="radio"
        name="custom-radio"
        className="peer hidden"
        checked={checked}
        disabled={disabled}
        onChange={onChange}
      />
      <span className="w-[26px] h-[26px] rounded-full border-2 border-blue-500 flex items-center justify-center peer-checked:bg-blue-500">
        <span className="w-3.5 h-3.5 rounded-full bg-white"></span>
      </span>
    </>
  );
};

export default Radio;
